    model: `PROCEDURE CountVowels(ThisString : STRING)
    DECLARE Index : INTEGER
    DECLARE ThisChar : STRING
    FOR Index <- 1 TO 6
        CharCount[Index] <- 0
    NEXT Index
    FOR Index <- 1 TO LENGTH(ThisString)
        ThisChar <- TO_LOWER(MID(ThisString, Index, 1))
        CASE OF ThisChar
            'a' : CharCount[1] <- CharCount[1] + 1
            'e' : CharCount[2] <- CharCount[2] + 1
            'i' : CharCount[3] <- CharCount[3] + 1
            'o' : CharCount[4] <- CharCount[4] + 1
            'u' : CharCount[5] <- CharCount[5] + 1
            'a' TO 'z' : CharCount[6] <- CharCount[6] + 1
        ENDCASE
    NEXT Index
    FOR Index <- 1 TO 6
        OUTPUT CharCount[Index]
    NEXT Index
ENDPROCEDURE`,
